        self.author = self._validate_string(author, "Author")
        self.category = category
        self.copies_available = self._validate_positive_int(copies_available)
        self.copies_total = copies_available

    def _validate_isbn(self, isbn):
        if not (len(str(isbn)) == 13 or len(str(isbn)) == 10):
            raise ValueError("ISBN must be 10 or 13 digits")
        return isbn

    def _validate_string(self, value, field_name):
        if not value or not isinstance(value, str):
            raise ValueError(f"{field_name} must be non-empty string")
        return value

    def _validate_positive_int(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError("Value must be non-negative integer")
        return value

    def borrow_copy(self):
        if self.copies_available > 0:
            self.copies_available -= 1
            return True
        return False

    def return_copy(self):
        if self.copies_available < self.copies_total:
            self.copies_available += 1
            return True
        return False
